        ci = inorder[i]
        cip1 = inorder[i + 1]
        if postorder_idx[ci] > postorder_idx[cip1]:
            graph[postorder_idx[cip1]].append(postorder_idx[ci])
        else:
            graph[postorder_idx[ci]].append(postorder_idx[cip1])
    return traverse(graph, n - 1)

def traverse(graph, node):
    if not graph[node]:
        return str(node)
    return traverse(graph, graph[node][0]) + traverse(graph, node)
