def generate_numbers(n, rules):
    queue = [n]
    visited = set()
    count = 0
    while queue:
        num = queue.pop(0)
        if num not in visited:
            visited.add(num)
            count += 1
            for rule in rules:
                new_num = None
                if rule[0] in str(num):
                    new_num = int(str(num).replace(str(rule[0]), str(rule[1])))
                if new_num not in visited and new_num not in queue:
                    queue.append(new_num)
    return count
