def calculate_arrangements(n, m, a) -> int:
    # Initialize an m by n array dp where dp[i][j] represents the number of ways to arrange i pots of flowers using j types
    dp = [[0] * (n+1) for _ in range(m+1)]
    dp[0][0] = 1

    # Fill in the dp table
    for i in range(1, m+1):
        for j in range(1, n+1):
            # If the current pot can be filled with any of the available types
            if j in a:
                # Add the number of ways to arrange the previous pot
                dp[i][j] += dp[i-1][j]
                # Add the number of ways to arrange the previous pot and add a new pot of the current type
                if j-1 >= 0:
                    dp[i][j] += dp[i-1][j-1]

    # Return the number of ways to arrange m pots using n types
    return dp[m][n] % (10**6 + 7)
