def calculate_arrangements(n, m, a):
    # Use memoization to store already computed arrangements
    memory = {}

    def recurse(i, j, arr):
        # Base case: no more pots to arrange
        if i == m:
            return 1

        # Base case: no more types of flowers left
        if i > n:
            return 0

        # Check if this subproblem has already been solved
        if (i, j) in memory:
            return memory[(i, j)]

        # Recursive case: add a pot of the current type of flower
        count = 0
        if j < a[i]:
            count += recurse(i + 1, j + 1, arr)

        # Recursive case: do not add a pot of the current type of flower
        count += recurse(i + 1, j, arr)

        # Store the result in the memory
        memory[(i, j)] = count % (10**6 + 7)

        return count

    return recurse(0, 0, [])
